// Package brandicons carries the provider marks the panel shows.
//
// They are extracted verbatim from the Jet Hub client bundle
// (dsh-codearts-auth lib/client/jet-hub.js, MIT) rather than linked from each
// vendor's site. That is deliberate: the vendor-favicon approach this replaced
// was wrong in three separate ways — several product domains serve no
// /favicon.ico at all, Huawei Cloud's icon is not the CodeArts mark, and
// Youdao's is not LobsterAI's. It also made every icon a different size and
// shape, where Jet Hub's set is visually consistent. Embedding the same bytes
// the reference plugin renders is what makes the two panels look alike, and it
// keeps the icons working with no outbound requests.
package brandicons

// CodeArts is the CodeArts (Huawei Cloud) mark.
const CodeArts = `data:image/png;base64,`

// CodeBuddy is the CodeBuddy (Tencent) mark. It serves both the China and international builds, which are the same product family.
const CodeBuddy = `data:image/png;base64,`

// WorkBuddy is the WorkBuddy mark, likewise shared by its China and international builds.
const WorkBuddy = `data:image/png;base64,`

// LobsterAI is the LobsterAI mark.
const LobsterAI = `data:image/svg+xml;base64,`

// Qoder is the Qoder mark.
const Qoder = `data:image/svg+xml;base64,`

// Trae is the TRAE mark.
const Trae = `data:image/svg+xml;base64,`

// Cline is the Cline mark.
const Cline = `data:image/png;base64,`

// Loomy is the Loomy (iFlytek) mark — a badge, because Jet Hub ships no artwork for this provider and neither does its site.
const Loomy = `data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"%3E%3Crect width="24" height="24" rx="6" fill="%23007aff"/%3E%3Ctext x="12" y="17.5" font-size="15" font-family="sans-serif" font-weight="700" fill="white" text-anchor="middle"%3EL%3C/text%3E%3C/svg%3E`

// Raccoon is the Raccoon Work (SenseTime) mark, added when that provider
// joined the set; Jet Hub ships artwork for it too, so the two panels stay
// identical.
const Raccoon = `data:image/png;base64,`
